const response = $input.first().json.response;
let analysis;
try {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  analysis = jsonMatch ? JSON.parse(jsonMatch[0]) : { incident: false, severity: 'unknown', type: 'parse_error', explanation: response };
} catch(e) {
  analysis = { incident: false, severity: 'unknown', type: 'parse_error', explanation: response };
}

return [{
  json: {
    ...analysis,
    timestamp: $('Parse Log').first().json.timestamp,
    raw_log: $('Parse Log').first().json.raw_log,
    source: $('Parse Log').first().json.source
  }
}];
